async function api(path,options={}){const r=await fetch(path.replace(/^\/api(?=\/|$)/,'api'),{...options,headers:{'content-type':'application/json',...options.headers}}),text=await r.text();let data={};if(text)try{data=JSON.parse(text)}catch{const error=Error(r.ok?'Ungültige Serverantwort':text);error.status=r.status;throw error}if(!r.ok){const error=Error(data.error||`HTTP ${r.status}`);error.status=r.status;throw error}if(data.warning)pendingWarning=data.warning;return data}
