function showError(e){const root=dialog.open?dialog:app;root.querySelector('[role=alert]')?.remove();root.insertAdjacentHTML('afterbegin',`<p class="error" role="alert" tabindex="-1">${esc(e.message)}</p>`);root.querySelector('[role=alert]').focus()}
