function localDateTime(value){if(!value)return'';const date=new Date(value);return Number.isNaN(date.getTime())?'':new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function contactFields(key,title,value){const person=JSON.parse(value||'{}'),open=Object.values(person).some(Boolean);return `<details class="form-section" ${open?'open':''}><summary>${title}</summary><div class="grid"><label>Name<input name="${key}Name" value="${esc(person.name)}"></label><label>Telefon<input name="${key}Phone" type="tel" value="${esc(person.phone)}"></label><label>Adresse<input name="${key}Address" value="${esc(person.address)}"></label></div></details>`}
