function reportTimes(report){return `<dl class="report-times"><div><dt>Alarmiert</dt><dd>${formatDateTime(report.alarmed_at)}</dd></div><div><dt>Ausgerückt</dt><dd>${formatDateTime(report.departed_at)}</dd></div><div><dt>Eingetroffen</dt><dd>${formatDateTime(report.arrived_at)}</dd></div><div><dt>Beendet</dt><dd>${formatDateTime(report.ended_at)}</dd></div><div><dt>Dauer</dt><dd>${durationText(report.alarmed_at,report.ended_at)}</dd></div></dl>`}
function contactSummary(title,value){const person=JSON.parse(value||'{}'),details=[person.name,person.phone,person.address].filter(Boolean);return details.length?`<p><b>${title}:</b> ${details.map(esc).join(' · ')}</p>`:''}
function commandSummary(value){const command=JSON.parse(value||'{}'),people=[['Gesamteinsatzleitung',command.rank,command.name],['Einsatzleitung der Einheit',command.additionalRank,command.additionalName]].filter(([,rank,name])=>rank||name);return people.length?`<p><b>Einsatzleitung:</b><br>${people.map(([label,rank,name])=>`${label}: ${[rank,name].filter(Boolean).map(esc).join(' ')}`).join('<br>')}</p>`:''}
function classificationSummary(value){const selected=JSON.parse(value||'{}'),rows=Object.entries(selected).filter(([,values])=>values?.length).map(([key,values])=>`<b>${esc(classificationLabels[key]||key)}:</b> ${values.map(esc).join(', ')}`);return rows.length?`<p>${rows.join('<br>')}</p>`:''}
async function renderCrew(selector,unitId,assignments,selected=[],request=''){
  const root=document.querySelector(selector),members=await api(`/api/units/${unitId}/members`);
  if(!root.isConnected||(request&&root.dataset.crewRequest!==request))return false;
  const vehicles=JSON.parse(assignments.find(a=>a.unitId===Number(unitId))?.vehicles||'[]').filter(vehicle=>typeof vehicle==='string'||vehicle.own!==false).map(vehicle=>typeof vehicle==='string'?vehicle:vehicle.name),chosen=new Map(selected.map(person=>[person.memberId,{...person,role:person.role==='mannschaft'?'besatzung':person.role}])),roles=[['maschinist','Maschinist'],['einheitsfuehrer','Einheitsführer'],['besatzung','Besatzung']];
  const zones=[{key:'available',vehicle:'',role:'',label:'Verfügbar'},{key:'none',vehicle:'',role:'besatzung',label:'Ohne Fahrzeug'},...vehicles.flatMap((vehicle,index)=>roles.map(([role,label])=>({key:`vehicle-${index}-${role}`,vehicle,role,label})))];
  const targetFor=member=>{const person=chosen.get(member.id);if(!person)return'available';if(!person.vehicle)return'none';return zones.find(zone=>zone.vehicle===person.vehicle&&zone.role===(person.role||'besatzung'))?.key||'available'};
  const options=current=>zones.map(zone=>`<option value="${zone.key}" ${current===zone.key?'selected':''}>${zone.key==='available'?'Nicht eingesetzt':zone.key==='none'?'Ohne Fahrzeug':`${esc(zone.vehicle)}: ${zone.label}`}</option>`).join('');
  const card=member=>{const current=targetFor(member);return `<article class="crew-person" draggable="${dragEnabled}" data-person="${member.id}"><strong>${esc(member.name)}</strong>${member.qualifications?`<small class="muted">${esc(member.qualifications)}</small>`:''}<select data-member="${member.id}" aria-label="Zuordnung für ${esc(member.name)}">${options(current)}</select></article>`};
  const cardsFor=key=>members.filter(member=>targetFor(member)===key).map(card).join('');
  const roleZone=zone=>`<section class="crew-zone crew-role" data-target="${zone.key}" data-vehicle="${esc(zone.vehicle)}" data-role="${zone.role}"><h5>${zone.label} <span data-count></span></h5><div class="crew-list">${cardsFor(zone.key)}</div></section>`;
  const restoreFocus=root.contains(document.activeElement);
  root.innerHTML=`<h3 tabindex="-1">Besatzung</h3><p class="muted">Auf Touch-Geräten oder mit Tastatur das Auswahlfeld verwenden; alternativ kann Personal mit der Maus gezogen werden.</p><div class="vehicle-board">${vehicles.map((vehicle,index)=>`<section class="vehicle-column"><h4>${esc(vehicle)}</h4>${roles.map(([role])=>roleZone(zones.find(zone=>zone.key===`vehicle-${index}-${role}`))).join('')}</section>`).join('')}<section class="vehicle-column"><h4>Ohne Fahrzeug</h4>${roleZone(zones.find(zone=>zone.key==='none'))}</section></div><details class="crew-available" open><summary>Verfügbares Personal</summary><section class="crew-zone crew-pool" data-target="available" data-vehicle="" data-role=""><h4>Mitglieder <span data-count></span></h4><div class="crew-list">${cardsFor('available')}</div></section></details>${members.length?'':'<p class="muted">Keine Mitglieder synchronisiert.</p>'}`;
  bindCrewBoard(root);
  if(restoreFocus)root.querySelector('h3').focus();
  return true;
}
function bindCrewBoard(root){
  const zones=[...root.querySelectorAll('.crew-zone')],cards=[...root.querySelectorAll('.crew-person')];
  const move=(card,target)=>{const zone=zones.find(item=>item.dataset.target===target);if(!card||!zone)return;if(['maschinist','einheitsfuehrer'].includes(zone.dataset.role)){const previous=zone.querySelector('.crew-person');if(previous&&previous!==card){const available=zones.find(item=>item.dataset.target==='available');previous.querySelector('[data-member]').value='available';available.querySelector('.crew-list').append(previous)}}card.querySelector('[data-member]').value=target;zone.querySelector('.crew-list').append(card);zones.forEach(updateCrewCount)};
  cards.forEach(card=>{if(dragEnabled){card.ondragstart=e=>{card.classList.add('dragging');e.dataTransfer.setData('text/plain',card.dataset.person)};card.ondragend=()=>card.classList.remove('dragging')}card.querySelector('[data-member]').onchange=e=>move(card,e.target.value)});
  zones.forEach(zone=>{zone.ondragover=e=>{e.preventDefault();zone.classList.add('over')};zone.ondragleave=()=>zone.classList.remove('over');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('over');move(cards.find(card=>card.dataset.person===e.dataTransfer.getData('text/plain')),zone.dataset.target)};updateCrewCount(zone)});
}
function updateCrewCount(zone){zone.querySelector('[data-count]').textContent=zone.querySelectorAll('.crew-person').length}
function crewSummary(value,vehicleNames=[]){const labels={einheitsfuehrer:'Einheitsführer',maschinist:'Maschinist',besatzung:'Besatzung'},order=Object.keys(labels),vehicles=new Map([...new Set(vehicleNames)].map(name=>[name,{}]));for(const person of JSON.parse(value||'[]')){const vehicle=person.vehicle||'Ohne Fahrzeug',role=person.role==='mannschaft'?'besatzung':order.includes(person.role)?person.role:'besatzung';if(!vehicles.has(vehicle))vehicles.set(vehicle,{});const roles=vehicles.get(vehicle);(roles[role]??=[]).push(person.name)}return [...vehicles].sort(([a],[b])=>a.localeCompare(b,'de')).map(([vehicle,roles])=>`${esc(vehicle)}: ${order.filter(role=>roles[role]?.length).map(role=>`${roles[role].map(esc).join(', ')} (${labels[role]})`).join('; ')||'Keine Besatzung'}`).join('<br>')||'Keine Besatzung'}
