function divera(){const allowed=me.role==='wehrleitung'?units:units.filter(u=>me.unitIds.includes(u.id)),maySync=me.role!=='fuehrungskraft';app.innerHTML=`<h1>DIVERA 24/7</h1>${maySync?`<section class="card"><h2>Konfiguration</h2><form id="divera" class="grid">
  <label>Einheit<select name="unitId">${allowed.map(u=>`<option value="${u.id}">${esc(u.name)}${u.divera_configured?' ✓':''}</option>`).join('')}</select></label>
  <label>Access-Key<input name="accessKey" type="password" required autocomplete="off"></label><button class="form-action">Speichern</button></form></section>`:''}
  <section class="card"><h2>Daten abrufen</h2><label>Einheit<select id="pullUnit">${allowed.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><p><button data-action="pullDivera">Einsätze abrufen</button>${maySync?' <button data-action="syncDivera" data-kind="members">Mitglieder synchronisieren</button> <button data-action="syncDivera" data-kind="vehicles">Fahrzeuge synchronisieren</button> <button data-action="syncDivera" data-kind="all">Alles synchronisieren</button>':''}</p><div id="diveraResults" role="status" aria-live="polite"></div></section>`;
  focusMain();if(maySync)bindForm('#divera',async d=>{await api(`/api/units/${d.unitId}/divera`,{method:'PUT',body:JSON.stringify(d)});await load();divera()})}
function importedForUnit(diveraId,unitId){return incidents.some(incident=>incident.divera_id===String(diveraId)&&JSON.parse(incident.assignments||'[]').some(assignment=>assignment.unitId===Number(unitId)))}
async function pullDivera(){const unitId=document.querySelector('#pullUnit').value,out=document.querySelector('#diveraResults');out.textContent='Lade …';try{const data=await api(`/api/units/${unitId}/divera`);out.innerHTML=data.alarms.map((a,i)=>{const imported=importedForUnit(a.id,unitId);return `<article class="report"><b>${esc(a.title)}</b><p>${esc(a.address)}<br><span class="muted">${a.vehicles.map(v=>`${esc(v.name)} · ${v.own?'eigene Einheit':'andere Einheit'}`).join(', ')}</span></p><button data-import="${i}" ${imported?'disabled':''}>${imported?'Bereits importiert':'Importieren'}</button></article>`}).join('')||'<p>Keine Einsätze gefunden.</p>';[...out.querySelectorAll('[data-import]')].forEach(button=>button.onclick=async()=>{await api(`/api/units/${unitId}/divera/import`,{method:'POST',body:JSON.stringify({id:data.alarms[Number(button.dataset.import)].id})});await load();divera()})}catch(e){out.innerHTML=`<p class="error" role="alert">${esc(e.message)}</p>`}}
async function syncDivera(kind){const unitId=document.querySelector('#pullUnit').value,out=document.querySelector('#diveraResults'),path=kind==='all'?'sync':`${kind}/sync`;out.textContent='Synchronisiere …';try{const result=await api(`/api/units/${unitId}/divera/${path}`,{method:'POST'});if(kind==='all')await load();out.innerHTML=kind==='all'?`<p>${result.members} Mitglieder, ${result.qualifications} Qualifikationen und ${result.vehicles} Fahrzeuge synchronisiert. ${result.incidentsCreated} Einsätze neu importiert, ${result.incidentsUpdated} aktualisiert.</p>`:`<p>${result.count} ${kind==='members'?'Mitglieder':'Fahrzeuge'} synchronisiert.</p>`}catch(e){out.innerHTML=`<p class="error" role="alert">${esc(e.message)}</p>`}}
start().catch(showError);
